F::custom(move |input| {
                // Guard C06 STRING/BINARY identities while leaving multi-argument
                // and raw nested CONCATs visible to CombineConcats.
                let string_binary_identity = match input.arguments.as_slice() {
                    [value]
                        if !matches!(value, expr::Expr::ScalarFunction(function)
                            if function.func.inner().is::<SparkConcat>()) =>
                    {
                        matches!(
                            value.get_type(input.function_context.schema),
                            Ok(DataType::Utf8
                                | DataType::LargeUtf8
                                | DataType::Utf8View
                                | DataType::Binary
                                | DataType::LargeBinary)
                        )
                    }
                    _ => false,
                };
                let value = concat(input)?;
                Ok(if string_binary_identity {
                    drop_inherited_column_metadata(value)
                } else {
                    value
                })
            })

F::custom(|input| {
                let (left, right) = input.arguments.two()?;
                let schema = input.function_context.schema;
                // Spark's NULLIF compares its arguments with `=`.
                reject_calendar_interval_ordering(
                    &[left.get_type(schema)?, right.get_type(schema)?],
                    "=",
                    "DATATYPE_MISMATCH.BINARY_OP_DIFF_TYPES",
                )?;
                Ok(ScalarUDF::from(SparkNullIf::new(
                    input.function_context.plan_config.ansi_mode,
                    input.function_context.plan_config.session_timezone.clone(),
                ))
                .call(vec![left, right]))
            })

F::custom(|input| match input.arguments.len() {
                2 => {
                    // A dictionary-encoded STRING formats as its STRING values do.
                    let arguments = input
                        .arguments
                        .into_iter()
                        .map(|arg| dictionary_string_values(arg, input.function_context.schema))
                        .collect::<PlanResult<Vec<_>>>()?;
                    Ok(date_format_with_args(
                        arguments,
                        input.function_context.plan_config,
                    ))
                }
                _ => Err(PlanError::invalid("date_format requires 2 arguments")),
            })

F::custom(|input| {
                let timestamp_ntz = matches!(
                    input.function_context.plan_config.default_timestamp_type,
                    DefaultTimestampType::TimestampNtz
                );
                to_timestamp(input, timestamp_ntz)
            })

F::custom(|input| {
                let timestamp_ntz = matches!(
                    input.function_context.plan_config.default_timestamp_type,
                    DefaultTimestampType::TimestampNtz
                );
                try_to_timestamp(input, timestamp_ntz)
            })

